export const getListWalletTransactionsUrl = (walletId: string, params: ListWalletTransactionsParams) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `${env.API_BASE_URL}/v1/wallets/${walletId}/transactions?${stringifiedParams}`
    : `${env.API_BASE_URL}/v1/wallets/${walletId}/transactions`
}

